import type { CliContext } from "./context.ts";
import { fetchMessage } from "../slack/messages.ts";
import { parseMsgTarget } from "./targets.ts";
import { resolveChannelId, resolveChannelName, normalizeChannelInput } from "../slack/channels.ts";
import { warnOnTruncatedSlackUrl } from "./message-url-warning.ts";
import { openDraftEditor } from "./draft-server.ts";
import { buildUnfurlApiParams } from "./unfurl-options.ts";

export async function composeMessage(input: {
  ctx: CliContext;
  targetInput: string;
  initialText?: string;
  options: { workspace?: string; threadTs?: string; unfurl?: boolean };
}): Promise<Record<string, unknown>> {
  const target = parseMsgTarget(String(input.targetInput));
  if (target.kind === "user") {
    throw new Error(
      "message compose does not support user ID targets. Use a channel name, channel ID, or message URL.",
    );
  }

  // URL target: resolve thread context and send
  if (target.kind === "url") {
    const { ref } = target;
    warnOnTruncatedSlackUrl(ref);
    return input.ctx.withAutoRefresh({
      workspaceUrl: ref.workspace_url,
      work: async () => {
        const { client } = await input.ctx.getClientForWorkspace(ref.workspace_url);
        const msg = await fetchMessage(client, { ref });
        const threadTs = input.options.threadTs ?? msg.thread_ts ?? msg.ts;
        const channelName = await resolveChannelName(client, ref.channel_id);

        return draftWithEditor({
          channelName,
          channelId: ref.channel_id,
          workspaceUrl: ref.workspace_url,
          threadTs,
          initialText: input.initialText,
          sendFn: async (text: string) => {
            const resp = await client.api("chat.postMessage", {
              channel: ref.channel_id,
              text,
              thread_ts: threadTs,
              ...buildUnfurlApiParams(input.options.unfurl),
            });
            return { ts: resp.ts as string };
          },
        });
      },
    });
  }

  // Channel name/ID target
  const workspaceUrl = input.ctx.effectiveWorkspaceUrl(input.options.workspace);
  await input.ctx.assertWorkspaceSpecifiedForChannelNames({
    workspaceUrl,
    channels: [String(target.channel)],
  });

  return input.ctx.withAutoRefresh({
    workspaceUrl,
    work: async () => {
      const { client } = await input.ctx.getClientForWorkspace(workspaceUrl);
      const channelId = await resolveChannelId(client, String(target.channel));
      const normalized = normalizeChannelInput(target.channel);
      const channelName =
        normalized.kind === "name" ? normalized.value : await resolveChannelName(client, channelId);

      return draftWithEditor({
        channelName,
        channelId,
        workspaceUrl,
        threadTs: input.options.threadTs,
        initialText: input.initialText,
        sendFn: async (text: string) => {
          const resp = await client.api("chat.postMessage", {
            channel: channelId,
            text,
            thread_ts: input.options.threadTs,
            ...buildUnfurlApiParams(input.options.unfurl),
          });
          return { ts: resp.ts as string };
        },
      });
    },
  });
}

async function draftWithEditor(input: {
  channelName: string;
  channelId: string;
  workspaceUrl?: string;
  threadTs?: string;
  initialText?: string;
  sendFn: (text: string) => Promise<{ ts: string }>;
}): Promise<Record<string, unknown>> {
  // In CI mode, skip the editor and send directly
  if (process.env.CI) {
    if (!input.initialText) {
      throw new Error("In CI mode, initial text is required (no editor available)");
    }
    const result = await input.sendFn(input.initialText);
    return { ok: true, sent: true, editor: "skipped", ts: result.ts };
  }

  const result = await openDraftEditor({
    channelName: input.channelName,
    channelId: input.channelId,
    workspaceUrl: input.workspaceUrl,
    threadTs: input.threadTs,
    initialText: input.initialText,
    onSend: input.sendFn,
  });

  if ("cancelled" in result) {
    return { ok: true, cancelled: true };
  }

  return { ok: true, sent: true };
}

import { describe, expect, test } from "bun:test";
import {
  parseReactionFilters,
  requireOldestWhenReactionFiltersUsed,
} from "../src/cli/message-actions.ts";
import { passesReactionNameFilters } from "../src/slack/messages.ts";

describe("parseReactionFilters", () => {
  test("normalizes shortcodes, names, and unicode", () => {
    const out = parseReactionFilters([":dart:", "dart", "🎯"]);
    expect(out).toEqual(["dart"]);
  });

  test("returns empty array when unset", () => {
    expect(parseReactionFilters(undefined)).toEqual([]);
  });
});

describe("passesReactionNameFilters", () => {
  test("matches when required reaction is present", () => {
    const msg = { reactions: [{ name: "dart" }] } as Record<string, unknown>;
    expect(passesReactionNameFilters(msg, { withReactions: ["dart"] })).toBe(true);
  });

  test("does not match when required reaction is missing", () => {
    const msg = { reactions: [{ name: "eyes" }] } as Record<string, unknown>;
    expect(passesReactionNameFilters(msg, { withReactions: ["dart"] })).toBe(false);
  });

  test("does not match when excluded reaction is present", () => {
    const msg = { reactions: [{ name: "dart" }] } as Record<string, unknown>;
    expect(passesReactionNameFilters(msg, { withoutReactions: ["dart"] })).toBe(false);
  });

  test("matches when excluded reaction is absent", () => {
    const msg = { reactions: [{ name: "eyes" }] } as Record<string, unknown>;
    expect(passesReactionNameFilters(msg, { withoutReactions: ["dart"] })).toBe(true);
  });

  test("supports with + without together", () => {
    const msg = { reactions: [{ name: "eyes" }, { name: "white_check_mark" }] } as Record<
      string,
      unknown
    >;
    expect(
      passesReactionNameFilters(msg, {
        withReactions: ["eyes"],
        withoutReactions: ["dart"],
      }),
    ).toBe(true);
  });
});

describe("requireOldestWhenReactionFiltersUsed", () => {
  test("returns oldest when no reaction filters are used", () => {
    expect(
      requireOldestWhenReactionFiltersUsed({
        oldest: undefined,
        withReactions: [],
        withoutReactions: [],
      }),
    ).toBeUndefined();
  });

  test("returns trimmed oldest when reaction filters are used", () => {
    expect(
      requireOldestWhenReactionFiltersUsed({
        oldest: " 1770165109.628379 ",
        withReactions: ["dart"],
        withoutReactions: [],
      }),
    ).toBe("1770165109.628379");
  });

  test("throws when reaction filters are used without oldest", () => {
    expect(() =>
      requireOldestWhenReactionFiltersUsed({
        oldest: undefined,
        withReactions: ["dart"],
        withoutReactions: [],
      }),
    ).toThrow('Reaction filters require --oldest "<seconds>.<micros>" to bound scan size.');
  });
});

import { describe, expect, test } from "bun:test";
import { toCompactMessage, type SlackMessageSummary } from "../src/slack/messages.ts";

describe("reactions compaction", () => {
  test("includes reactions only when enabled", () => {
    const msg: SlackMessageSummary = {
      channel_id: "C1",
      ts: "1.000001",
      text: "hi",
      markdown: "hi",
      reactions: [{ name: "rocket", users: ["U12345678", "U87654321"], count: 2 }],
    };

    const a = toCompactMessage(msg, { includeReactions: false });
    expect(a.reactions).toBeUndefined();

    const b = toCompactMessage(msg, { includeReactions: true });
    expect(b.reactions?.[0]?.name).toBe("rocket");
    expect(b.reactions?.[0]?.users?.length).toBe(2);
    expect(b.reactions?.[0]?.count).toBeUndefined();
  });

  test("preserves W-prefixed user IDs while compacting reactions", () => {
    const msg: SlackMessageSummary = {
      channel_id: "C1",
      ts: "1.000001",
      text: "hi",
      markdown: "hi",
      reactions: [{ name: "eyes", users: ["W12345678", "B12345678"], count: 2 }],
    };

    const compact = toCompactMessage(msg, { includeReactions: true });
    expect(compact.reactions?.[0]?.users).toEqual(["W12345678"]);
    expect(compact.reactions?.[0]?.count).toBe(2);
  });

  test("adds forwarded thread metadata for shared messages with thread_ts", () => {
    const msg: SlackMessageSummary = {
      channel_id: "C1",
      ts: "1.000001",
      text: "outer",
      markdown: "outer",
      attachments: [
        {
          is_share: true,
          reply_count: 4,
          from_url:
            "https://example.slack.com/archives/C222/p333?thread_ts=1771564510.386389&cid=C222",
        },
      ],
    };

    const compact = toCompactMessage(msg);
    expect(compact.forwarded_threads?.length).toBe(1);
    expect(compact.forwarded_threads?.[0]?.thread_ts).toBe("1771564510.386389");
    expect(compact.forwarded_threads?.[0]?.channel_id).toBe("C222");
    expect(compact.forwarded_threads?.[0]?.reply_count).toBe(4);
  });
});

import { afterEach, beforeEach, describe, expect, mock, spyOn, test } from "bun:test";
import { mkdtemp, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { Command } from "commander";
import type { CliContext } from "../src/cli/context.ts";
import {
  createDraftAction,
  deleteDraftAction,
  listDraftsAction,
  updateDraftAction,
} from "../src/cli/message-draft-actions.ts";
import { registerMessageDraftCommand } from "../src/cli/message-draft-command.ts";

type Call = { method: string; params: Record<string, unknown> };

/**
 * Build a mock CliContext whose client records every api() call and answers
 * drafts.* / conversations.info from the supplied fixtures. Mirrors the
 * createContext helper in message-send.test.ts.
 */
function createContext(
  calls: Call[],
  fixtures: {
    draftsList?: Record<string, unknown>[];
    channelInfo?: Record<string, Record<string, unknown>>;
    /** First call to this method returns ok:false invalid_auth (for retry tests). */
    failOnce?: "drafts.create" | "drafts.update";
    /** Every call to this method returns ok:false with the given error. */
    failWith?: { method: "drafts.create" | "drafts.update"; error: string };
    /** Simulate withAutoRefresh retrying work once on an invalid_auth error. */
    retryOnAuth?: boolean;
  } = {},
) {
  const failedOnce = { current: false };
  const client = {
    api: async (method: string, params: Record<string, unknown> = {}) => {
      calls.push({ method, params });
      switch (method) {
        case "drafts.list":
          return { ok: true, drafts: fixtures.draftsList ?? [] };
        case "drafts.create":
        case "drafts.update": {
          // Simulate a transient auth failure on the first call to this method,
          // then succeed on retry — exercises withAutoRefresh's work() re-run.
          if (fixtures.failOnce === method && !failedOnce.current) {
            failedOnce.current = true;
            return { ok: false, error: "invalid_auth" };
          }
          // Simulate a persistent failure (e.g. stale conflict) on every call.
          if (fixtures.failWith?.method === method) {
            return { ok: false, error: fixtures.failWith.error };
          }
          return method === "drafts.create"
            ? { ok: true, draft: { id: "DrNew", destinations: params.destinations } }
            : {
                ok: true,
                draft: { id: String(params.draft_id), destinations: params.destinations },
              };
        }
        case "drafts.delete":
          return { ok: true };
        case "conversations.open":
          return { ok: true, channel: { id: "D99999999" } };
        case "conversations.info": {
          const info = fixtures.channelInfo?.[String(params.channel)];
          return info ? { ok: true, channel: info } : { ok: true };
        }
        case "files.getUploadURLExternal":
          // file_id derived from filename so multi-file uploads stay distinct.
          return {
            ok: true,
            upload_url: "https://upload.example/f",
            file_id: `F-${params.filename}`,
          };
        case "files.completeUploadExternal": {
          const files = (params.files as { id?: unknown }[] | undefined) ?? [];
          return { ok: true, files: files.map((f) => ({ id: String(f?.id ?? "F?"), title: "t" })) };
        }
        default:
          return { ok: true };
      }
    },
  };

  return {
    effectiveWorkspaceUrl: (flag?: string) => flag,
    assertWorkspaceSpecifiedForChannelNames: async () => {},
    withAutoRefresh: async <T>(input: {
      workspaceUrl: string | undefined;
      work: () => Promise<T>;
    }) => {
      // Mirror the real helper: retry work() once when it throws an auth error.
      if (!fixtures.retryOnAuth) {
        return input.work();
      }
      try {
        return await input.work();
      } catch (err: unknown) {
        const message = err instanceof Error ? err.message : String(err);
        if (/(?:^|[^a-z])(invalid_auth|token_expired)(?:$|[^a-z])/i.test(message)) {
          return await input.work();
        }
        throw err;
      }
    },
    getClientForWorkspace: async () => ({
      client: client as never,
      auth: { auth_type: "standard", token: "x" as const },
      workspace_url: "https://workspace.slack.com",
    }),
    normalizeUrl: (u: string) => u,
    errorMessage: (err: unknown) => (err instanceof Error ? err.message : String(err)),
    parseContentType: () => "any",
    parseCurl: () => ({
      workspace_url: "https://workspace.slack.com",
      xoxc_token: "xoxc-1",
      xoxd_cookie: "xoxd-1",
    }),
    importDesktop: async () => ({
      cookie_d: "",
      teams: [],
      source: { leveldb_path: "", cookies_path: "" },
    }),
    importChrome: () => ({ cookie_d: "", teams: [] }),
    importBrave: async () => null,
    importFirefox: async () => null,
  } satisfies CliContext;
}

function draftsUpdateCall(calls: Call[]): Call {
  const call = calls.find((c) => c.method === "drafts.update");
  if (!call) {
    throw new Error("expected a drafts.update call");
  }
  return call;
}

describe("createDraftAction", () => {
  test("creates a draft addressed to a channel id", async () => {
    const calls: Call[] = [];
    const ctx = createContext(calls);

    const result = await createDraftAction({
      ctx,
      targetInput: "C11111111",
      text: "hello",
      options: { workspace: "https://workspace.slack.com" },
    });

    const create = calls.find((c) => c.method === "drafts.create");
    expect(create).toBeDefined();
    expect(create?.params.destinations).toEqual([{ channel_id: "C11111111" }]);
    expect(Array.isArray(create?.params.blocks)).toBe(true);
    expect(result).toEqual({
      ok: true,
      draft: { id: "DrNew", destinations: [{ channel_id: "C11111111" }] },
    });
  });

  test("rejects --broadcast without a thread", async () => {
    const calls: Call[] = [];
    const ctx = createContext(calls);

    await expect(
      createDraftAction({
        ctx,
        targetInput: "C11111111",
        text: "hello",
        options: { workspace: "https://workspace.slack.com", broadcast: true },
      }),
    ).rejects.toThrow(/--broadcast requires a thread/);
    expect(calls.some((c) => c.method === "drafts.create")).toBe(false);
  });

  test("rejects --broadcast for a DM (user) target", async () => {
    const calls: Call[] = [];
    const ctx = createContext(calls);

    await expect(
      createDraftAction({
        ctx,
        targetInput: "W12345678",
        text: "hello",
        options: {
          workspace: "https://workspace.slack.com",
          threadTs: "1700000000.100000",
          broadcast: true,
        },
      }),
    ).rejects.toThrow(/not supported for DM targets/);
    expect(calls.some((c) => c.method === "drafts.create")).toBe(false);
  });

  test("rejects --broadcast for a D... channel-id (DM) target", async () => {
    const calls: Call[] = [];
    const ctx = createContext(calls);

    await expect(
      createDraftAction({
        ctx,
        targetInput: "D12345678",
        text: "hello",
        options: {
          workspace: "https://workspace.slack.com",
          threadTs: "1700000000.100000",
          broadcast: true,
        },
      }),
    ).rejects.toThrow(/not supported for DM targets/);
    expect(calls.some((c) => c.method === "drafts.create")).toBe(false);
  });

  test("rejects --broadcast on a channel name with no thread before any network call", async () => {
    const calls: Call[] = [];
    const ctx = createContext(calls);

    await expect(
      createDraftAction({
        ctx,
        targetInput: "general",
        text: "x",
        options: { workspace: "https://workspace.slack.com", broadcast: true },
      }),
    ).rejects.toThrow(/--broadcast requires a thread/);
    // The real problem (no thread) is reported without a channel-resolution round-trip.
    expect(calls.length).toBe(0);
  });

  test("rejects --broadcast on a DM message URL before fetching the message", async () => {
    const calls: Call[] = [];
    const ctx = createContext(calls);

    await expect(
      createDraftAction({
        ctx,
        targetInput: "https://workspace.slack.com/archives/D12345678/p1700000000100000",
        text: "x",
        options: { broadcast: true },
      }),
    ).rejects.toThrow(/not supported for DM targets/);
    expect(calls.length).toBe(0);
  });

  test("uploads --attach files and wires their file ids into the draft", async () => {
    const calls: Call[] = [];
    const ctx = createContext(calls);
    const dir = await mkdtemp(join(tmpdir(), "agent-slack-draft-create-attach-"));
    const a = join(dir, "a.png");
    const b = join(dir, "b.pdf");
    await writeFile(a, "x");
    await writeFile(b, "y");
    const originalFetch = globalThis.fetch;
    globalThis.fetch = mock(
      async () => new Response("", { status: 200 }),
    ) as unknown as typeof fetch;

    try {
      await createDraftAction({
        ctx,
        targetInput: "C11111111",
        text: "see attached",
        options: { workspace: "https://workspace.slack.com", attach: [a, b] },
      });
    } finally {
      globalThis.fetch = originalFetch;
      await rm(dir, { recursive: true, force: true });
    }

    const methods = calls.map((c) => c.method);
    // Batch upload: stage every file first, then one completion call, then the draft.
    expect(methods).toEqual([
      "files.getUploadURLExternal",
      "files.getUploadURLExternal",
      "files.completeUploadExternal",
      "drafts.create",
    ]);
    expect(calls.filter((c) => c.method === "files.completeUploadExternal")).toHaveLength(1);
    const create = calls.at(-1)!;
    expect(create.params.file_ids).toEqual(["F-a.png", "F-b.pdf"]);
  });

  test("aborts before any upload or drafts.create when an --attach path is missing", async () => {
    const calls: Call[] = [];
    const ctx = createContext(calls);

    await expect(
      createDraftAction({
        ctx,
        targetInput: "C11111111",
        text: "nope",
        options: {
          workspace: "https://workspace.slack.com",
          attach: [join(tmpdir(), "agent-slack-nonexistent-attach.png")],
        },
      }),
    ).rejects.toThrow();
    expect(calls.some((c) => c.method === "drafts.create")).toBe(false);
    expect(calls.some((c) => c.method === "files.getUploadURLExternal")).toBe(false);
  });
});

describe("updateDraftAction", () => {
  const threadedBroadcastDraft = {
    id: "Dr123",
    blocks: [],
    destinations: [{ channel_id: "C11111111", thread_ts: "1700000000.100000", broadcast: true }],
    last_updated_ts: "1700000000.123",
    file_ids: ["F1", "F2"],
  };

  test("text-only edit preserves destination, thread, broadcast, and file ids", async () => {
    const calls: Call[] = [];
    const ctx = createContext(calls, { draftsList: [threadedBroadcastDraft] });

    await updateDraftAction({
      ctx,
      draftId: "Dr123",
      text: "revised",
      options: { workspace: "https://workspace.slack.com" },
    });

    const update = draftsUpdateCall(calls);
    // conflict-detection ts is auto-fetched and padded to 7 fractional digits.
    expect(update.params.client_last_updated_ts).toBe("1700000000.1230000");
    expect(update.params.destinations).toEqual([
      { channel_id: "C11111111", thread_ts: "1700000000.100000", broadcast: true },
    ]);
    expect(update.params.file_ids).toEqual(["F1", "F2"]);
  });

  test("re-addressing a broadcast thread draft to a non-thread channel clears broadcast instead of erroring", async () => {
    const calls: Call[] = [];
    const ctx = createContext(calls, { draftsList: [threadedBroadcastDraft] });

    // Regression: an inherited broadcast flag must not become a one-way ratchet
    // that fails the "broadcast requires a thread" guard on a non-thread target.
    await updateDraftAction({
      ctx,
      draftId: "Dr123",
      text: "revised",
      options: { workspace: "https://workspace.slack.com", channel: "C99999999" },
    });

    const update = draftsUpdateCall(calls);
    expect(update.params.destinations).toEqual([{ channel_id: "C99999999" }]);
  });

  test("explicit --broadcast on a non-thread draft still errors", async () => {
    const calls: Call[] = [];
    const ctx = createContext(calls, {
      draftsList: [
        {
          id: "Dr123",
          blocks: [],
          destinations: [{ channel_id: "C11111111" }],
          last_updated_ts: "1700000000.5",
        },
      ],
    });

    await expect(
      updateDraftAction({
        ctx,
        draftId: "Dr123",
        text: "revised",
        options: { workspace: "https://workspace.slack.com", broadcast: true },
      }),
    ).rejects.toThrow(/--broadcast requires a thread/);
    expect(calls.some((c) => c.method === "drafts.update")).toBe(false);
  });

  test("refuses to update a scheduled draft rather than clearing its schedule", async () => {
    const calls: Call[] = [];
    const ctx = createContext(calls, {
      draftsList: [
        {
          id: "Dr123",
          blocks: [],
          destinations: [{ channel_id: "C11111111" }],
          last_updated_ts: "1700000000.5",
          date_scheduled: 1800000000,
        },
      ],
    });

    await expect(
      updateDraftAction({
        ctx,
        draftId: "Dr123",
        text: "revised",
        options: { workspace: "https://workspace.slack.com" },
      }),
    ).rejects.toThrow(/scheduled send time/);
    expect(calls.some((c) => c.method === "drafts.update")).toBe(false);
  });

  test("refuses a text-only update on a multi-destination draft, but allows re-addressing", async () => {
    const multiDest = {
      id: "Dr123",
      blocks: [],
      destinations: [{ channel_id: "C11111111" }, { channel_id: "C22222222" }],
      last_updated_ts: "1700000000.5",
    };

    // Text-only: would drop the second recipient — must throw.
    const calls1: Call[] = [];
    await expect(
      updateDraftAction({
        ctx: createContext(calls1, { draftsList: [multiDest] }),
        draftId: "Dr123",
        text: "revised",
        options: { workspace: "https://workspace.slack.com" },
      }),
    ).rejects.toThrow(/multiple destinations/);
    expect(calls1.some((c) => c.method === "drafts.update")).toBe(false);

    // Explicit re-address is an intentional single-destination move — allowed.
    const calls2: Call[] = [];
    await updateDraftAction({
      ctx: createContext(calls2, { draftsList: [multiDest] }),
      draftId: "Dr123",
      text: "revised",
      options: { workspace: "https://workspace.slack.com", channel: "C99999999" },
    });
    expect(draftsUpdateCall(calls2).params.destinations).toEqual([{ channel_id: "C99999999" }]);
  });

  test("re-addressing to a different thread does not inherit the old broadcast flag", async () => {
    const calls: Call[] = [];
    const ctx = createContext(calls, { draftsList: [threadedBroadcastDraft] });

    await updateDraftAction({
      ctx,
      draftId: "Dr123",
      text: "revised",
      options: {
        workspace: "https://workspace.slack.com",
        channel: "C22222222",
        threadTs: "1700000000.200000",
      },
    });

    // Regression: --channel resets broadcast to explicit-only, so moving to a
    // new thread must not carry broadcast:true from the old destination.
    expect(draftsUpdateCall(calls).params.destinations).toEqual([
      { channel_id: "C22222222", thread_ts: "1700000000.200000", broadcast: false },
    ]);
  });

  test("--no-broadcast clears an inherited broadcast flag on a same-thread edit", async () => {
    const calls: Call[] = [];
    const ctx = createContext(calls, { draftsList: [threadedBroadcastDraft] });

    await updateDraftAction({
      ctx,
      draftId: "Dr123",
      text: "revised",
      options: { workspace: "https://workspace.slack.com", broadcast: false },
    });

    expect(draftsUpdateCall(calls).params.destinations).toEqual([
      { channel_id: "C11111111", thread_ts: "1700000000.100000", broadcast: false },
    ]);
  });

  test("rejects --broadcast when re-addressing to a DM (user) target", async () => {
    const calls: Call[] = [];
    const ctx = createContext(calls, { draftsList: [threadedBroadcastDraft] });

