function loadBlocksFromPath(path: string): unknown[] {
  const raw = path === "-" ? readFileSync(0, "utf8") : readFileSync(path, "utf8");
  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch (err) {
    throw new Error(
      `--blocks: failed to parse JSON from ${path === "-" ? "stdin" : path}: ${(err as Error).message}`,
    );
  }
  if (!Array.isArray(parsed)) {
    throw new Error(`--blocks: expected a JSON array of Block Kit blocks, got ${typeof parsed}`);
  }
  for (let i = 0; i < parsed.length; i++) {
    const el = parsed[i];
    if (el === null || typeof el !== "object" || Array.isArray(el)) {
      throw new Error(
        `--blocks: element at index ${i} is not a Block Kit block object (got ${el === null ? "null" : Array.isArray(el) ? "array" : typeof el})`,
      );
    }
  }
  return parsed;
}

export type MessageCommandOptions = {
  maxBodyChars: string;
  workspace?: string;
  ts?: string;
  threadTs?: string;
  limit?: string;
  oldest?: string;
  latest?: string;
  withReaction?: string[];
  withoutReaction?: string[];
  includeReactions?: boolean;
  resolveUsers?: boolean;
  refreshUsers?: boolean;
};

export function parseLimit(raw: string | undefined): number | undefined {
  if (raw === undefined) {
    return undefined;
  }
  const n = Number.parseInt(raw, 10);
  if (!Number.isFinite(n) || n < 1) {
    throw new Error(`Invalid --limit value "${raw}": must be a positive integer`);
  }
  return n;
}

export function requireMessageTs(raw: string | undefined): string {
  const ts = raw?.trim();
  if (!ts) {
    throw new Error('When targeting a channel, you must pass --ts "<seconds>.<micros>"');
  }
  return ts;
}

export function parseReactionFilters(raw: string[] | undefined): string[] {
  if (!Array.isArray(raw) || raw.length === 0) {
    return [];
  }
  const out: string[] = [];
  for (const value of raw) {
    const normalized = normalizeSlackReactionName(String(value));
    if (!out.includes(normalized)) {
      out.push(normalized);
    }
  }
  return out;
}

export function requireOldestWhenReactionFiltersUsed(input: {
  oldest?: string;
  withReactions: string[];
  withoutReactions: string[];
}): string | undefined {
  const hasReactionFilters = input.withReactions.length > 0 || input.withoutReactions.length > 0;
  const oldest = input.oldest?.trim();
  if (!hasReactionFilters) {
    return oldest;
  }
  if (!oldest) {
    throw new Error(
      'Reaction filters require --oldest "<seconds>.<micros>" to bound scan size. Example: --oldest "1770165109.628379"',
    );
  }
  return oldest;
}

export async function sendMessage(input: {
  ctx: CliContext;
  targetInput: string;
  text: string;
  options: {
    workspace?: string;
    threadTs?: string;
    attach?: string[];
    blocks?: string;
    replyBroadcast?: boolean;
    schedule?: string;
    scheduleIn?: string;
    unfurl?: boolean;
  };
}): Promise<Record<string, unknown>> {
  const target = parseMsgTarget(String(input.targetInput));
  const attachPaths = normalizeAttachPaths(input.options.attach);
  const postAt = resolveSchedulePostAt({
    schedule: input.options.schedule,
    scheduleIn: input.options.scheduleIn,
  });
  if (postAt !== undefined && attachPaths.length > 0) {
    throw new Error(
      "--schedule/--schedule-in cannot be combined with --attach (Slack scheduled messages do not support file uploads).",
    );
  }
  if (input.options.unfurl === false && attachPaths.length > 0) {
    throw new Error(
      "--no-unfurl cannot be combined with --attach (Slack file uploads do not accept unfurl parameters).",
    );
  }
  const formattedText = formatOutboundSlackText(input.text);
  const blocks = input.options.blocks
    ? loadBlocksFromPath(input.options.blocks)
    : input.text
      ? textToRichTextBlocks(input.text)
      : null;

  if (target.kind === "url") {
    const { ref } = target;
    warnOnTruncatedSlackUrl(ref);
    return await input.ctx.withAutoRefresh({
      workspaceUrl: ref.workspace_url,
      work: async () => {
        const { client, workspace_url } = await input.ctx.getClientForWorkspace(ref.workspace_url);
        const msg = await fetchMessage(client, { ref });
        const threadTs = msg.thread_ts ?? msg.ts;
        return await sendMessageToChannel({
          client,
          workspaceUrl: workspace_url ?? ref.workspace_url,
          channelId: ref.channel_id,
          text: formattedText,
          blocks,
          threadTs,
          replyBroadcast: input.options.replyBroadcast,
          attachPaths,
          postAt,
          unfurl: input.options.unfurl,
        });
      },
    });
  }

  if (target.kind === "user") {
    if (input.options.replyBroadcast) {
      throw new Error("--reply-broadcast is not supported for DM targets");
    }
    const workspaceUrl = input.ctx.effectiveWorkspaceUrl(input.options.workspace);
    return await input.ctx.withAutoRefresh({
      workspaceUrl,
      work: async () => {
        const { client, workspace_url } = await input.ctx.getClientForWorkspace(workspaceUrl);
        const dmChannelId = await openDmChannel(client, target.userId);
        return await sendMessageToChannel({
          client,
          workspaceUrl: workspace_url ?? workspaceUrl,
          channelId: dmChannelId,
          text: formattedText,
          blocks,
          attachPaths,
          postAt,
          unfurl: input.options.unfurl,
        });
      },
    });
  }

  if (input.options.replyBroadcast && !input.options.threadTs) {
    throw new Error("--reply-broadcast requires --thread-ts for channel targets");
  }
  const workspaceUrl = input.ctx.effectiveWorkspaceUrl(input.options.workspace);
  await input.ctx.assertWorkspaceSpecifiedForChannelNames({
    workspaceUrl,
    channels: [String(target.channel)],
  });
  return await input.ctx.withAutoRefresh({
    workspaceUrl,
    work: async () => {
      const { client, workspace_url } = await input.ctx.getClientForWorkspace(workspaceUrl);
      const channelId = await resolveChannelId(client, String(target.channel));
      return await sendMessageToChannel({
        client,
        workspaceUrl: workspace_url ?? workspaceUrl,
        channelId,
        text: formattedText,
        blocks,
        threadTs: input.options.threadTs ? String(input.options.threadTs) : undefined,
        replyBroadcast: input.options.replyBroadcast,
        attachPaths,
        postAt,
        unfurl: input.options.unfurl,
      });
    },
  });
}

async function sendMessageToChannel(input: {
  client: SlackApiClient;
  workspaceUrl?: string;
  channelId: string;
  text: string;
  blocks?: unknown[] | null;
  threadTs?: string;
  replyBroadcast?: boolean;
  attachPaths: string[];
  postAt?: number;
  unfurl?: boolean;
}): Promise<Record<string, unknown>> {
  if (input.postAt !== undefined) {
    const resp = await input.client.api("chat.scheduleMessage", {
      channel: input.channelId,
      text: input.text,
      post_at: input.postAt,
      thread_ts: input.threadTs,
      ...(input.blocks ? { blocks: input.blocks } : {}),
      ...(input.replyBroadcast && input.threadTs ? { reply_broadcast: true } : {}),
      ...buildUnfurlApiParams(input.unfurl),
    });
    const channelId = typeof resp.channel === "string" ? resp.channel : input.channelId;
    const scheduledMessageId =
      typeof resp.scheduled_message_id === "string" ? resp.scheduled_message_id : undefined;
    return {
      ok: true,
      channel_id: channelId,
      scheduled_message_id: scheduledMessageId,
      post_at: getResponseNumber(resp.post_at) ?? input.postAt,
      thread_ts: input.threadTs,
    };
  }

  if (input.attachPaths.length === 0) {
    const resp = await input.client.api("chat.postMessage", {
      channel: input.channelId,
      text: input.text,
      thread_ts: input.threadTs,
      ...(input.blocks ? { blocks: input.blocks } : {}),
      ...(input.replyBroadcast && input.threadTs ? { reply_broadcast: true } : {}),
      ...buildUnfurlApiParams(input.unfurl),
    });
    const ts = typeof resp.ts === "string" ? resp.ts : undefined;
    const channelId = typeof resp.channel === "string" ? resp.channel : input.channelId;
    const permalink =
      input.workspaceUrl && ts
        ? buildSlackMessageUrl({
            workspace_url: input.workspaceUrl,
            channel_id: channelId,
            message_ts: ts,
            thread_ts: input.threadTs,
          })
        : undefined;
    return {
      ok: true,
      channel_id: channelId,
      ts,
      thread_ts: input.threadTs,
      permalink,
    };
  }

  if (input.blocks) {
    process.stderr.write(
      "Warning: rich text formatting is not supported with file attachments; sending as plain text.\n",
    );
  }

  let initialComment = input.text;
  for (const filePath of input.attachPaths) {
    await uploadLocalFileToSlack({
      client: input.client,
      channelId: input.channelId,
      filePath,
      threadTs: input.threadTs,
      initialComment,
    });
    initialComment = "";
  }

  return {
    ok: true,
    channel_id: input.channelId,
    thread_ts: input.threadTs,
  };
}

function getResponseNumber(value: unknown): number | undefined {
  if (typeof value === "number") {
    return value;
  }
  if (typeof value === "string" && value.trim()) {
    const parsed = Number(value);
    return Number.isFinite(parsed) ? parsed : undefined;
  }
  return undefined;
}

export async function editMessage(input: {
  ctx: CliContext;
  targetInput: string;
  text: string;
  options: { workspace?: string; ts?: string; blocks?: string };
}): Promise<Record<string, unknown>> {
  const target = parseMsgTarget(String(input.targetInput));
  if (target.kind === "user") {
    throw new Error(
      "message edit does not support user ID targets. Use a channel name, channel ID, or message URL.",
    );
  }
  const workspaceUrl = input.ctx.effectiveWorkspaceUrl(input.options.workspace);
  const formattedText = formatOutboundSlackText(input.text);
  const blocks = input.options.blocks
    ? loadBlocksFromPath(input.options.blocks)
    : input.text
      ? textToRichTextBlocks(input.text)
      : null;

  await input.ctx.withAutoRefresh({
    workspaceUrl: target.kind === "url" ? target.ref.workspace_url : workspaceUrl,
    work: async () => {
      if (target.kind === "url") {
        const { ref } = target;
        warnOnTruncatedSlackUrl(ref);
        const { client } = await input.ctx.getClientForWorkspace(ref.workspace_url);
        await client.api("chat.update", {
          channel: ref.channel_id,
          ts: ref.message_ts,
          text: formattedText,
          ...(blocks ? { blocks } : {}),
        });
        return;
      }

      const ts = requireMessageTs(input.options.ts);
      await input.ctx.assertWorkspaceSpecifiedForChannelNames({
        workspaceUrl,
        channels: [target.channel],
      });
      const { client } = await input.ctx.getClientForWorkspace(workspaceUrl);
      const channelId = await resolveChannelId(client, target.channel);
      await client.api("chat.update", {
        channel: channelId,
        ts,
        text: formattedText,
        ...(blocks ? { blocks } : {}),
      });
    },
  });

  return { ok: true };
}

export async function deleteMessage(input: {
  ctx: CliContext;
  targetInput: string;
  options: { workspace?: string; ts?: string };
}): Promise<Record<string, unknown>> {
  const target = parseMsgTarget(String(input.targetInput));
