export async function reactOnTarget(input: {
  ctx: CliContext;
  action: "add" | "remove";
  targetInput: string;
  emoji: string;
  options?: { workspace?: string; ts?: string };
}): Promise<Record<string, unknown>> {
  const target = parseMsgTarget(input.targetInput);
  if (target.kind === "user") {
    throw new Error(
      "react does not support user ID targets. Use a channel name, channel ID, or message URL.",
    );
  }
  const workspaceUrl = input.ctx.effectiveWorkspaceUrl(input.options?.workspace);

  await input.ctx.withAutoRefresh({
    workspaceUrl: target.kind === "url" ? target.ref.workspace_url : workspaceUrl,
    work: async () => {
      if (target.kind === "url") {
        const { ref } = target;
        warnOnTruncatedSlackUrl(ref);
        const { client } = await input.ctx.getClientForWorkspace(ref.workspace_url);
        const name = normalizeSlackReactionName(input.emoji);
        await client.api(`reactions.${input.action}`, {
          channel: ref.channel_id,
          timestamp: ref.message_ts,
          name,
        });
        return;
      }

      const ts = requireMessageTs(input.options?.ts);

      await input.ctx.assertWorkspaceSpecifiedForChannelNames({
        workspaceUrl,
        channels: [target.channel],
      });

      const { client } = await input.ctx.getClientForWorkspace(workspaceUrl);
      const channelId = await resolveChannelId(client, target.channel);
      const name = normalizeSlackReactionName(input.emoji);
      await client.api(`reactions.${input.action}`, {
        channel: channelId,
        timestamp: ts,
        name,
      });
    },
  });

  return { ok: true };
}

export { handleMessageGet, handleMessageList } from "./message-read-actions.ts";

import type { CliContext } from "./context.ts";
import { parseMsgTarget } from "./targets.ts";
import { openDmChannel, resolveChannelId } from "../slack/channels.ts";
import type { SlackApiClient } from "../slack/client.ts";
import {
  cancelScheduledMessage as cancelScheduledMessageApi,
  listScheduledMessages as listScheduledMessagesApi,
  normalizeScheduleLimit,
} from "../slack/scheduled-messages.ts";

export async function listScheduledMessages(input: {
  ctx: CliContext;
  options: {
    workspace?: string;
    channel?: string;
    cursor?: string;
    oldest?: string;
    latest?: string;
    limit?: string;
  };
}): Promise<Record<string, unknown>> {
  const channelTarget = input.options.channel
    ? parseMsgTarget(String(input.options.channel))
    : undefined;
  const workspaceUrl =
    channelTarget?.kind === "url"
      ? channelTarget.ref.workspace_url
      : input.ctx.effectiveWorkspaceUrl(input.options.workspace);
  if (channelTarget?.kind === "channel") {
    await input.ctx.assertWorkspaceSpecifiedForChannelNames({
      workspaceUrl,
      channels: [channelTarget.channel],
    });
  }

  return await input.ctx.withAutoRefresh({
    workspaceUrl,
    work: async () => {
      const { client } = await input.ctx.getClientForWorkspace(workspaceUrl);
      const channelId = channelTarget
        ? await resolveScheduledChannelTarget(client, channelTarget)
        : undefined;
      return await listScheduledMessagesApi(client, {
        channelId,
        cursor: input.options.cursor,
        oldest: input.options.oldest,
        latest: input.options.latest,
        limit: normalizeScheduleLimit(input.options.limit),
      });
    },
  });
}

export async function cancelScheduledMessage(input: {
  ctx: CliContext;
  scheduledMessageId: string;
  options: { workspace?: string; channel: string };
}): Promise<Record<string, unknown>> {
  const channelTarget = parseMsgTarget(String(input.options.channel));
  const workspaceUrl =
    channelTarget.kind === "url"
      ? channelTarget.ref.workspace_url
      : input.ctx.effectiveWorkspaceUrl(input.options.workspace);
  if (channelTarget.kind === "channel") {
    await input.ctx.assertWorkspaceSpecifiedForChannelNames({
      workspaceUrl,
      channels: [channelTarget.channel],
    });
  }

  return await input.ctx.withAutoRefresh({
    workspaceUrl,
    work: async () => {
      const { client } = await input.ctx.getClientForWorkspace(workspaceUrl);
      const channelId = await resolveScheduledChannelTarget(client, channelTarget);
      await cancelScheduledMessageApi(client, {
        channelId,
        scheduledMessageId: input.scheduledMessageId,
      });
      return {
        ok: true,
        channel_id: channelId,
        scheduled_message_id: input.scheduledMessageId,
      };
    },
  });
}

async function resolveScheduledChannelTarget(
  client: SlackApiClient,
  target: ReturnType<typeof parseMsgTarget>,
): Promise<string> {
  if (target.kind === "url") {
    return target.ref.channel_id;
  }
  if (target.kind === "user") {
    return await openDmChannel(client, target.userId);
  }
  return await resolveChannelId(client, target.channel);
}

import type { CliContext } from "./context.ts";
import {
  fetchMessage,
  fetchThread,
  fetchChannelHistory,
  toCompactMessage,
} from "../slack/messages.ts";
import { pruneEmpty } from "../lib/compact-json.ts";
import { parseMsgTarget } from "./targets.ts";
import { resolveChannelId } from "../slack/channels.ts";
import { downloadMessageFiles } from "./message-file-downloads.ts";
import { warnOnTruncatedSlackUrl } from "./message-url-warning.ts";
import { getThreadSummary, toThreadListMessage } from "./message-thread-info.ts";
import type { MessageCommandOptions } from "./message-actions.ts";
import {
  parseLimit,
  parseReactionFilters,
  requireOldestWhenReactionFiltersUsed,
} from "./message-actions.ts";
import {
  collectReferencedUserIds,
  resolveUsersById,
  toReferencedUsers,
} from "../slack/user-cache.ts";

export async function handleMessageGet(input: {
  ctx: CliContext;
  targetInput: string;
  options: MessageCommandOptions;
}): Promise<Record<string, unknown>> {
  const target = parseMsgTarget(input.targetInput);
  if (target.kind === "user") {
    throw new Error(
      "message get does not support user ID targets. Use a channel name, channel ID, or message URL.",
    );
  }
  const workspaceUrl = input.ctx.effectiveWorkspaceUrl(input.options.workspace);

  return input.ctx.withAutoRefresh({
    workspaceUrl: target.kind === "url" ? target.ref.workspace_url : workspaceUrl,
    work: async () => {
      if (target.kind === "url") {
        const { ref } = target;
        warnOnTruncatedSlackUrl(ref);
        const { client, auth } = await input.ctx.getClientForWorkspace(ref.workspace_url);
        const includeReactions = Boolean(input.options.includeReactions);
        const msg = await fetchMessage(client, { ref, includeReactions });
        const thread = await getThreadSummary(client, { channelId: ref.channel_id, msg });
        const downloadedPaths = await downloadMessageFiles({ auth, messages: [msg] });
        const maxBodyChars = Number.parseInt(input.options.maxBodyChars, 10);
        const referencedUserIds = collectReferencedUserIds([msg], {
          includeReactions,
        });
        const usersById =
          input.options.resolveUsers || input.options.refreshUsers
            ? await resolveUsersById({
                client,
                workspaceUrl: ref.workspace_url,
                userIds: referencedUserIds,
                forceRefresh: Boolean(input.options.refreshUsers),
              })
            : new Map();
        const message = toCompactMessage(msg, {
          maxBodyChars,
          includeReactions,
          downloadedPaths,
        });
        return pruneEmpty({
          message,
          thread,
          referenced_users: toReferencedUsers(referencedUserIds, usersById),
        }) as Record<string, unknown>;
      }

      const ts = input.options.ts?.trim();
      if (!ts) {
        throw new Error('When targeting a channel, you must pass --ts "<seconds>.<micros>"');
      }

      await input.ctx.assertWorkspaceSpecifiedForChannelNames({
        workspaceUrl,
        channels: [target.channel],
      });

      const includeReactions = Boolean(input.options.includeReactions);
      const { client, auth, workspace_url } = await input.ctx.getClientForWorkspace(workspaceUrl);
      const channelId = await resolveChannelId(client, target.channel);
      const ref = {
        workspace_url: workspace_url ?? workspaceUrl ?? "",
        channel_id: channelId,
        message_ts: ts,
        thread_ts_hint: input.options.threadTs?.trim() || undefined,
        raw: input.targetInput,
      };

      const msg = await fetchMessage(client, { ref, includeReactions });
      const thread = await getThreadSummary(client, { channelId, msg });
      const downloadedPaths = await downloadMessageFiles({ auth, messages: [msg] });
      const maxBodyChars = Number.parseInt(input.options.maxBodyChars, 10);
      const referencedUserIds = collectReferencedUserIds([msg], {
        includeReactions,
      });
      const usersById =
        input.options.resolveUsers || input.options.refreshUsers
          ? await resolveUsersById({
              client,
              workspaceUrl: ref.workspace_url,
              userIds: referencedUserIds,
              forceRefresh: Boolean(input.options.refreshUsers),
            })
          : new Map();
      const message = toCompactMessage(msg, {
        maxBodyChars,
        includeReactions,
        downloadedPaths,
      });
      return pruneEmpty({
        message,
        thread,
        referenced_users: toReferencedUsers(referencedUserIds, usersById),
      }) as Record<string, unknown>;
    },
  });
}

export async function handleMessageList(input: {
  ctx: CliContext;
  targetInput: string;
  options: MessageCommandOptions;
}): Promise<Record<string, unknown>> {
  const target = parseMsgTarget(input.targetInput);
  if (target.kind === "user") {
    throw new Error(
      "message list does not support user ID targets. Use a channel name, channel ID, or message URL.",
    );
  }
  const workspaceUrl = input.ctx.effectiveWorkspaceUrl(input.options.workspace);

  return input.ctx.withAutoRefresh({
    workspaceUrl: target.kind === "url" ? target.ref.workspace_url : workspaceUrl,
    work: async () => {
      const withReactions = parseReactionFilters(input.options.withReaction);
      const withoutReactions = parseReactionFilters(input.options.withoutReaction);
      const hasReactionFilters = withReactions.length > 0 || withoutReactions.length > 0;

      if (target.kind === "url") {
        if (hasReactionFilters) {
          throw new Error(
            "Reaction filters are only supported for channel history mode (not message URL thread mode)",
          );
        }
        const { ref } = target;
        warnOnTruncatedSlackUrl(ref);
        const { client, auth } = await input.ctx.getClientForWorkspace(ref.workspace_url);
        const includeReactions = Boolean(input.options.includeReactions);
        const msg = await fetchMessage(client, { ref, includeReactions });
        const rootTs = msg.thread_ts ?? msg.ts;
        const threadMessages = await fetchThread(client, {
          channelId: ref.channel_id,
          threadTs: rootTs,
          includeReactions,
        });
        const downloadedPaths = await downloadMessageFiles({ auth, messages: threadMessages });
        const maxBodyChars = Number.parseInt(input.options.maxBodyChars, 10);
        const referencedUserIds = collectReferencedUserIds(threadMessages, {
          includeReactions,
        });
        const usersById =
          input.options.resolveUsers || input.options.refreshUsers
            ? await resolveUsersById({
                client,
                workspaceUrl: ref.workspace_url,
                userIds: referencedUserIds,
                forceRefresh: Boolean(input.options.refreshUsers),
              })
            : new Map();
        return pruneEmpty({
          messages: threadMessages
            .map((m) => toCompactMessage(m, { maxBodyChars, includeReactions, downloadedPaths }))
            .map(toThreadListMessage),
          referenced_users: toReferencedUsers(referencedUserIds, usersById),
        }) as Record<string, unknown>;
      }

      const { client, auth, workspace_url } = await input.ctx.getClientForWorkspace(workspaceUrl);

      await input.ctx.assertWorkspaceSpecifiedForChannelNames({
        workspaceUrl,
        channels: [target.channel],
      });

      const channelId = await resolveChannelId(client, target.channel);

      const threadTs = input.options.threadTs?.trim();
      const ts = input.options.ts?.trim();

      // No thread specifier → list recent channel messages
      if (!threadTs && !ts) {
        const includeReactions = Boolean(input.options.includeReactions);
        const limit = parseLimit(input.options.limit);
        const oldest = requireOldestWhenReactionFiltersUsed({
          oldest: input.options.oldest,
          withReactions,
          withoutReactions,
        });
        const channelMessages = await fetchChannelHistory(client, {
          channelId,
          limit,
          latest: input.options.latest?.trim(),
          oldest,
          includeReactions: includeReactions || hasReactionFilters,
          withReactions,
          withoutReactions,
        });
        const downloadedPaths = await downloadMessageFiles({ auth, messages: channelMessages });
        const maxBodyChars = Number.parseInt(input.options.maxBodyChars, 10);
        const referencedUserIds = collectReferencedUserIds(channelMessages, {
          includeReactions,
        });
        const usersById =
          input.options.resolveUsers || input.options.refreshUsers
            ? await resolveUsersById({
                client,
                workspaceUrl: workspace_url ?? workspaceUrl ?? "",
                userIds: referencedUserIds,
                forceRefresh: Boolean(input.options.refreshUsers),
              })
            : new Map();
        return pruneEmpty({
          channel_id: channelId,
          messages: channelMessages.map((m) =>
            toCompactMessage(m, { maxBodyChars, includeReactions, downloadedPaths }),
          ),
          referenced_users: toReferencedUsers(referencedUserIds, usersById),
        }) as Record<string, unknown>;
      }

      if (hasReactionFilters) {
        throw new Error(
          "Reaction filters are only supported for channel history mode (without --thread-ts/--ts)",
        );
      }

      const rootTs =
        threadTs ??
        (await (async () => {
          const ref = {
            workspace_url: workspace_url ?? workspaceUrl ?? "",
            channel_id: channelId,
            message_ts: ts!,
            raw: input.targetInput,
          };
          const includeReactions = Boolean(input.options.includeReactions);
          const msg = await fetchMessage(client, { ref, includeReactions });
          return msg.thread_ts ?? msg.ts;
        })());

      const includeReactions = Boolean(input.options.includeReactions);
      const threadMessages = await fetchThread(client, {
        channelId,
        threadTs: rootTs,
        includeReactions,
      });
      const downloadedPaths = await downloadMessageFiles({ auth, messages: threadMessages });
      const maxBodyChars = Number.parseInt(input.options.maxBodyChars, 10);
      const referencedUserIds = collectReferencedUserIds(threadMessages, {
        includeReactions,
      });
      const usersById =
        input.options.resolveUsers || input.options.refreshUsers
          ? await resolveUsersById({
              client,
              workspaceUrl: workspace_url ?? workspaceUrl ?? "",
              userIds: referencedUserIds,
              forceRefresh: Boolean(input.options.refreshUsers),
            })
          : new Map();
      return pruneEmpty({
        messages: threadMessages
          .map((m) => toCompactMessage(m, { maxBodyChars, includeReactions, downloadedPaths }))
          .map(toThreadListMessage),
        referenced_users: toReferencedUsers(referencedUserIds, usersById),
      }) as Record<string, unknown>;
    },
  });
}

import { pbkdf2Sync, createDecipheriv } from "node:crypto";

export function decryptChromiumCookieValue(
  data: Buffer,
  options: { password: string; iterations: number },
): string {
  if (!data || data.length === 0) {
    return "";
  }

  const { password, iterations } = options;

  if (iterations < 1) {
    throw new RangeError(`iterations must be >= 1, got ${iterations}`);
  }

  const salt = Buffer.from("saltysalt", "utf8");
  const iv = Buffer.alloc(16, " ");
  const key = pbkdf2Sync(password, salt, iterations, 16, "sha1");

  const decipher = createDecipheriv("aes-128-cbc", key, iv);
  decipher.setAutoPadding(true);
  const plain = Buffer.concat([decipher.update(data), decipher.final()]);
  const marker = Buffer.from("xoxd-");
  const idx = plain.indexOf(marker);
  if (idx === -1) {
    return plain.toString("utf8");
  }

  let end = idx;
  while (end < plain.length) {
    const b = plain[end]!;
    if (b < 0x21 || b > 0x7e) {
      break;
    }
    end++;
  }
  const rawToken = plain.subarray(idx, end).toString("utf8");
  try {
    return decodeURIComponent(rawToken);
  } catch {
    return rawToken;
  }
}

export type ParsedCurlTokens = {
  workspace_url: string;
  xoxc_token: string;
  xoxd_cookie: string;
};

export function parseSlackCurlCommand(curlInput: string): ParsedCurlTokens {
  const urlMatch = curlInput.match(/curl\s+['"]?(https?:\/\/([^.]+)\.slack\.com[^'"\s]*)/i);
  if (!urlMatch) {
    throw new Error("Could not find Slack workspace URL in cURL command");
  }
  const workspace_url = `https://${urlMatch[2]}.slack.com`;

  const cookieMatch = curlInput.match(
    /(?:-b|--cookie)\s+\$?'([^']+)'|(?:-b|--cookie)\s+\$?"([^"]+)"|-H\s+\$?'[Cc]ookie:\s*([^']+)'|-H\s+\$?"[Cc]ookie:\s*([^"]+)"/,
  );
  const cookieHeader = cookieMatch
    ? cookieMatch[1] || cookieMatch[2] || cookieMatch[3] || cookieMatch[4] || ""
    : "";
  const xoxdMatch = cookieHeader.match(/(?:^|;\s*)d=(xoxd-[^;]+)/);
  if (!xoxdMatch) {
    throw new Error("Could not find xoxd cookie (d=xoxd-...) in cURL command");
  }
  const xoxd_cookie = decodeURIComponent(xoxdMatch[1]!);

  // Token can appear in various forms: token=..., "token":"...", or name="token"... in form bodies.
  // Try common patterns first, then fall back to the first xoxc-* we can find.
  const tokenPatterns: RegExp[] = [
    /(?:^|[?&\s])token=(xoxc-[A-Za-z0-9-]+)/,
    /"token"\s*:\s*"(xoxc-[A-Za-z0-9-]+)"/,
    /name="token"[^x]*?(xoxc-[A-Za-z0-9-]+)/,
    /\b(xoxc-[A-Za-z0-9-]+)\b/,
  ];

  let xoxc_token: string | null = null;
  for (const re of tokenPatterns) {
    const m = curlInput.match(re);
    if (m?.[1]) {
      const [, token] = m;
      xoxc_token = token ?? null;
      break;
    }
  }
  if (!xoxc_token) {
    throw new Error("Could not find xoxc token in cURL command");
  }

  return { workspace_url, xoxc_token, xoxd_cookie };
}

import { platform } from "node:os";
import { execFileSync } from "node:child_process";

const IS_MACOS = platform() === "darwin";
const DEFAULT_KEYCHAIN_TIMEOUT_MS = 3_000;

export function getKeychainTimeoutMs(): number {
  const raw = process.env.AGENT_SLACK_KEYCHAIN_TIMEOUT_MS?.trim();
  if (!raw) {
    return DEFAULT_KEYCHAIN_TIMEOUT_MS;
  }
  const parsed = Number(raw);
  if (!Number.isFinite(parsed) || parsed <= 0) {
    return DEFAULT_KEYCHAIN_TIMEOUT_MS;
  }
  return Math.floor(parsed);
}

export function keychainGet(account: string, service: string): string | null {
  if (!IS_MACOS) {
    return null;
  }
  try {
    const result = execFileSync(
      "security",
      ["find-generic-password", "-s", service, "-a", account, "-w"],
      {
        encoding: "utf8",
        stdio: ["pipe", "pipe", "ignore"],
        timeout: getKeychainTimeoutMs(),
      },
    );
    return result.trim() || null;
  } catch {
    return null;
  }
}

export function keychainSet(input: { account: string; value: string; service: string }): boolean {
  if (!IS_MACOS) {
    return false;
  }
  const { account, value, service } = input;
  try {
    try {
      execFileSync("security", ["delete-generic-password", "-s", service, "-a", account], {
        stdio: ["pipe", "pipe", "ignore"],
        timeout: getKeychainTimeoutMs(),
      });
    } catch {
      // ignore
    }
    execFileSync("security", ["add-generic-password", "-s", service, "-a", account, "-w", value], {
      stdio: "pipe",
      timeout: getKeychainTimeoutMs(),
    });
    return true;
  } catch {
    return false;
  }
}

import { z } from "zod";

export const WorkspaceAuthSchema = z.union([
  z.object({
    auth_type: z.literal("standard"),
    token: z.string().min(1),
  }),
  z.object({
    auth_type: z.literal("browser"),
    xoxc_token: z.string().min(1),
    xoxd_cookie: z.string().min(1),
  }),
]);

export type WorkspaceAuth = z.infer<typeof WorkspaceAuthSchema>;

export const WorkspaceSchema = z.object({
  workspace_url: z.string().url(),
  workspace_name: z.string().optional(),
  team_id: z.string().optional(),
  team_domain: z.string().optional(),
  auth: WorkspaceAuthSchema,
});

export type Workspace = z.infer<typeof WorkspaceSchema>;

export const CredentialsSchema = z.object({
  version: z.literal(1),
  updated_at: z.string().optional(),
  default_workspace_url: z.string().url().optional(),
  workspaces: z.array(WorkspaceSchema).default([]),
});

export type Credentials = z.infer<typeof CredentialsSchema>;

